/**
 * Runs a Facebook Pages action through the core's ConnectorClient, with the configured
 * mode and credentials. Each request is built exactly as the action's own class
 * and the flow executor build it: one description, three callers.
 */
class FacebookPagesClient
{
    /** @param array<string,mixed> $settings config('connectors.<slug>') */
    public function __construct(
        protected readonly array $settings = [],
        protected readonly ?ConnectorClient $client = null,
    ) {}

    /**
     * @param  array<string,mixed>  $config  the action's own config, as on the canvas
     * @param  array<string,string>|null  $credentials  this connection's, for a multi-account app
     */
    public function call(
        string $operation,
        array $config = [],
        mixed $input = null,
        ?string $idempotencyKey = null,
        ?array $credentials = null,
        ?Transport $transport = null,
    ): ConnectorResult {
        $config += ['mode' => $this->settings['mode'] ?? 'auto'];
        $credentials ??= array_filter(
            (array) ($this->settings['credentials'] ?? []),
            static fn ($value): bool => $value !== null && $value !== '',
        );

        return match ($operation) {
            PostCreate::OPERATION => $this->postCreate($config, $input, $idempotencyKey, $credentials, $transport),
            default => throw new InvalidArgumentException('facebook_pages: '.$operation.' is not an action of this connector.'),
        };
