     */
    private function postCreate(array $config, mixed $input, ?string $idempotencyKey, array $credentials, ?Transport $transport): ConnectorResult
    {
        unset($idempotencyKey);
        $result = ($this->client ?? new ConnectorClient)->call(
            FacebookPages::descriptor(),
            PostCreate::OPERATION,
            $config,
            [
                'method' => PostCreate::METHOD,
                'path' => PostCreate::path($config),
                'json' => PostCreate::body($config),
            ],
            $input,
            credentials: $credentials === [] ? null : $credentials,
            transport: $transport,
        );

        return $result;
    }
